// Package postgres implements channel.Repository against PostgreSQL
// via jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"slices"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/cowork/internal/channel"
	"github.com/garamsh/garam/cowork/internal/channel/postgres/db"
	"github.com/garamsh/garam/platform/sdk/errorx"
	"github.com/garamsh/garam/platform/sdk/grn"
)

// The SQL states the adapter reads: a channel name the organization
// already has, and a reference to a channel or message that is gone.
const (
	uniqueViolation     = "23505"
	foreignKeyViolation = "23503"
)

// Repository implements channel.Repository against PostgreSQL.
type Repository struct {
	pool *pgxpool.Pool
}

var _ channel.Repository = (*Repository)(nil)

// New answers a repository over pool.
func New(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool}
}

// translate turns a driver error into the domain's. notFound is what a
// missing row means for the call.
func translate(err error, op string, notFound error) error {
	var pgErr *pgconn.PgError
	switch {
	case err == nil:
		return nil
	case errors.Is(err, pgx.ErrNoRows):
		return notFound
	case errors.As(err, &pgErr) && pgErr.Code == uniqueViolation:
		return channel.ErrNameTaken
	case errors.As(err, &pgErr) && pgErr.Code == foreignKeyViolation:
		return notFound
	case errorx.KindOf(err) != errorx.KindUnknown:
		return err
	}
	return errorx.Wrap(err, "channels: "+op, errorx.KindUnavailable)
}

func grns(ss []string) ([]grn.GRN, error) {
	out := make([]grn.GRN, 0, len(ss))
	for _, s := range ss {
		g, err := grn.Parse(s)
		if err != nil {
			return nil, errorx.Wrap(err, "channels: stored GRN", errorx.KindDataLoss)
		}
		out = append(out, g)
	}
	return out, nil
}

func strs(gs []grn.GRN) []string {
	out := make([]string, len(gs))
	for i, g := range gs {
		out[i] = g.String()
	}
	return out
}

func channelOf(r db.Channel, members []string) (channel.Channel, error) {
	creator, err := grn.Parse(r.CreatedBy)
	if err != nil {
		return channel.Channel{}, errorx.Wrap(err, "channels: stored creator", errorx.KindDataLoss)
	}
	ms, err := grns(members)
	if err != nil {
		return channel.Channel{}, err
	}
	return channel.Channel{
		ID: r.ID, Org: r.Org, Kind: channel.Kind(r.Kind), Name: r.Name,
		CreatedBy: creator, CreatedAt: r.CreatedAt.Time, Members: ms,
	}, nil
}

// row is the columns every message query answers, whichever struct
// sqlc generated for it.
type row struct {
	org, id, channel string
	thread           pgtype.Text
	author, body     string
	mentions, pages  []string
	createdAt        pgtype.Timestamptz
	replies          int32
}

func messageOf(r row) (channel.Message, error) {
	author, err := grn.Parse(r.author)
	if err != nil {
		return channel.Message{}, errorx.Wrap(err, "channels: stored author", errorx.KindDataLoss)
	}
	mentions, err := grns(r.mentions)
	if err != nil {
		return channel.Message{}, err
	}
	return channel.Message{
		ID: r.id, Org: r.org, Channel: r.channel, Thread: r.thread.String, Author: author, Body: r.body,
		Mentions: mentions, Pages: r.pages, CreatedAt: r.createdAt.Time, Replies: int(r.replies),
	}, nil
}

func messagesOf(rows []row) ([]channel.Message, error) {
	out := make([]channel.Message, 0, len(rows))
	for _, r := range rows {
		m, err := messageOf(r)
		if err != nil {
			return nil, err
		}
		out = append(out, m)
	}
	return out, nil
}

// Create implements channel.Repository.
func (r *Repository) Create(ctx context.Context, c channel.Channel) error {
	err := pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		if err := q.InsertChannel(ctx, db.InsertChannelParams{
			Org: c.Org, ID: c.ID, Kind: string(c.Kind), Name: c.Name, CreatedBy: c.CreatedBy.String(),
			CreatedAt: pgtype.Timestamptz{Time: c.CreatedAt, Valid: true},
		}); err != nil {
			return err
		}
		for _, m := range c.Members {
			if err := q.InsertMember(ctx, db.InsertMemberParams{Org: c.Org, ChannelID: c.ID, Member: m.String()}); err != nil {
				return err
			}
		}
		return nil
	})
	return translate(err, "create", channel.ErrChannelNotFound)
}

// Get implements channel.Repository.
func (r *Repository) Get(ctx context.Context, org, id string) (channel.Channel, error) {
	q := db.New(r.pool)
	c, err := q.GetChannel(ctx, db.GetChannelParams{Org: org, ID: id})
	if err != nil {
		return channel.Channel{}, translate(err, "get", channel.ErrChannelNotFound)
	}
	members, err := q.ListMembers(ctx, db.ListMembersParams{Org: org, ChannelID: id})
	if err != nil {
		return channel.Channel{}, translate(err, "get", channel.ErrChannelNotFound)
	}
	return channelOf(c, members)
}

// List implements channel.Repository.
func (r *Repository) List(ctx context.Context, org string, member grn.GRN) ([]channel.Channel, error) {
	q := db.New(r.pool)
	rows, err := q.ListChannels(ctx, db.ListChannelsParams{Org: org, Member: member.String()})
	if err != nil {
		return nil, translate(err, "list", channel.ErrChannelNotFound)
	}
	ids := make([]string, len(rows))
	for i, c := range rows {
		ids[i] = c.ID
	}
	memberRows, err := q.ListMembersOf(ctx, db.ListMembersOfParams{Org: org, Channels: ids})
	if err != nil {
		return nil, translate(err, "list", channel.ErrChannelNotFound)
	}
	members := map[string][]string{}
	for _, m := range memberRows {
		members[m.ChannelID] = append(members[m.ChannelID], m.Member)
	}
	out := make([]channel.Channel, 0, len(rows))
	for _, c := range rows {
		ch, err := channelOf(c, members[c.ID])
		if err != nil {
			return nil, err
		}
		out = append(out, ch)
	}
	return out, nil
}

// AddMember implements channel.Repository.
func (r *Repository) AddMember(ctx context.Context, org, id string, member grn.GRN) error {
	err := db.New(r.pool).InsertMember(ctx, db.InsertMemberParams{Org: org, ChannelID: id, Member: member.String()})
	return translate(err, "add member", channel.ErrChannelNotFound)
}

// RemoveMember implements channel.Repository.
func (r *Repository) RemoveMember(ctx context.Context, org, id string, member grn.GRN) error {
	err := db.New(r.pool).DeleteMember(ctx, db.DeleteMemberParams{Org: org, ChannelID: id, Member: member.String()})
	return translate(err, "remove member", channel.ErrChannelNotFound)
}

// Post implements channel.Repository.
func (r *Repository) Post(ctx context.Context, m channel.Message) (channel.Message, error) {
	err := pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		if m.Thread != "" {
			root, err := q.GetMessage(ctx, db.GetMessageParams{Org: m.Org, ID: m.Thread})
			if err != nil {
				return err
			}
			if root.ChannelID != m.Channel {
				return channel.ErrMessageNotFound
			}
			if root.ThreadID.Valid {
				m.Thread = root.ThreadID.String
			}
		}
		return q.InsertMessage(ctx, db.InsertMessageParams{
			Org: m.Org, ID: m.ID, ChannelID: m.Channel,
			ThreadID: pgtype.Text{String: m.Thread, Valid: m.Thread != ""},
			Author:   m.Author.String(), Body: m.Body, Mentions: strs(m.Mentions), Pages: append([]string{}, m.Pages...),
			CreatedAt: pgtype.Timestamptz{Time: m.CreatedAt, Valid: true},
		})
	})
	if err != nil {
		return channel.Message{}, translate(err, "post", channel.ErrMessageNotFound)
	}
	return m, nil
}

// GetMessage implements channel.Repository.
func (r *Repository) GetMessage(ctx context.Context, org, id string) (channel.Message, error) {
	m, err := db.New(r.pool).GetMessage(ctx, db.GetMessageParams{Org: org, ID: id})
	if err != nil {
		return channel.Message{}, translate(err, "get message", channel.ErrMessageNotFound)
	}
	return messageOf(row{m.Org, m.ID, m.ChannelID, m.ThreadID, m.Author, m.Body, m.Mentions, m.Pages, m.CreatedAt, 0})
}

// Messages implements channel.Repository. The query reads newest
// first, so the last limit are the ones read; they are answered oldest
// first.
func (r *Repository) Messages(ctx context.Context, org, id, before string, limit int) ([]channel.Message, error) {
	rows, err := db.New(r.pool).ListMessages(ctx, db.ListMessagesParams{Org: org, ChannelID: id, Before: before, Lim: int32(limit)})
	if err != nil {
		return nil, translate(err, "messages", channel.ErrChannelNotFound)
	}
	out := make([]row, len(rows))
	for i, m := range rows {
		out[i] = row{m.Org, m.ID, m.ChannelID, m.ThreadID, m.Author, m.Body, m.Mentions, m.Pages, m.CreatedAt, m.Replies}
	}
	slices.Reverse(out)
	return messagesOf(out)
}

// Thread implements channel.Repository.
func (r *Repository) Thread(ctx context.Context, org, id string) ([]channel.Message, error) {
	rows, err := db.New(r.pool).ListThread(ctx, db.ListThreadParams{Org: org, ID: id})
	if err != nil {
		return nil, translate(err, "thread", channel.ErrMessageNotFound)
	}
	if len(rows) == 0 {
		return nil, channel.ErrMessageNotFound
	}
	out := make([]row, len(rows))
	for i, m := range rows {
		out[i] = row{m.Org, m.ID, m.ChannelID, m.ThreadID, m.Author, m.Body, m.Mentions, m.Pages, m.CreatedAt, 0}
	}
	return messagesOf(out)
}

// Search implements channel.Repository with Postgres full-text search
// over the body, in its language-neutral configuration. query is read
// as a web search reads one: words, "quoted phrases", -exclusions.
func (r *Repository) Search(ctx context.Context, org string, channels []string, query string, limit int) ([]channel.Message, error) {
	rows, err := db.New(r.pool).SearchMessages(ctx, db.SearchMessagesParams{Org: org, Channels: channels, Query: query, Lim: int32(limit)})
	if err != nil {
		return nil, translate(err, "search", channel.ErrChannelNotFound)
	}
	out := make([]row, len(rows))
	for i, m := range rows {
		out[i] = row{m.Org, m.ID, m.ChannelID, m.ThreadID, m.Author, m.Body, m.Mentions, m.Pages, m.CreatedAt, 0}
	}
	return messagesOf(out)
}

// Linking implements channel.Repository.
func (r *Repository) Linking(ctx context.Context, org string, channels []string, page string, limit int) ([]channel.Message, error) {
	rows, err := db.New(r.pool).ListLinking(ctx, db.ListLinkingParams{Org: org, Channels: channels, Page: page, Lim: int32(limit)})
	if err != nil {
		return nil, translate(err, "linking", channel.ErrChannelNotFound)
	}
	out := make([]row, len(rows))
	for i, m := range rows {
		out[i] = row{m.Org, m.ID, m.ChannelID, m.ThreadID, m.Author, m.Body, m.Mentions, m.Pages, m.CreatedAt, 0}
	}
	return messagesOf(out)
}
